// Fail closed unless worker provides governed validation proof.
// Preserves ALL downstream fields: package, cache/mode, cost, narrative data.
const input = $input.first().json;
if (!input.workerValidated) {
  throw new Error('ReportContentPackage not validated by worker — rejecting');
}
if (!input.packageHash || typeof input.packageHash !== 'string' || input.packageHash.length !== 64) {
  throw new Error('Missing or invalid packageHash from worker');
}
// Preserve the complete worker envelope for downstream nodes.
// Worker is authoritative; n8n does not re-validate schema or modify fields.
return [{ json: input }];

// Cost preflight executed in worker before this node
const estimate = $input.first().json.costEstimate;
if (!estimate.allowed) {
  throw new Error('Cost preflight rejected: ' + estimate.reason);
}
return [{ json: $input.first().json }];

// SSRF defense: strict hostname allowlist + HTTPS-only + block internal addresses.
const ALLOWED_HOSTS = new Set([
  'api.openai.com',
  'api.anthropic.com',
  // Add additional approved model hosts here after governance review
]);
const BLOCKED_PATTERNS = [
  /^localhost$/i, /^127\./, /^0\./, /^10\./, /^172\.1[6-9]\./, /^172\.2[0-9]\./, /^172\.3[0-1]\./, /^192\.168\./, /^169\.254\./, /^::1$/, /^fc00:/, /^fe80:/
];
const endpoint = $json.modelEndpoint;
if (!endpoint || typeof endpoint !== 'string') {
  throw new Error('modelEndpoint is required and must be a string');
}
let url;
try { url = new URL(endpoint); } catch (e) {
  throw new Error('modelEndpoint is not a valid URL: ' + endpoint);
}
if (url.protocol !== 'https:') {
  throw new Error('modelEndpoint must use HTTPS, got: ' + url.protocol);
}
if (!ALLOWED_HOSTS.has(url.hostname)) {
  throw new Error('modelEndpoint host not in strict allowlist: ' + url.hostname);
}
for (const pat of BLOCKED_PATTERNS) {
  if (pat.test(url.hostname)) {
    throw new Error('modelEndpoint resolves to blocked address: ' + url.hostname);
  }
}
// Inject validated endpoint back — worker must use this, not webhook-supplied value
$json._validatedEndpoint = endpoint;
return [{ json: $json }];

// Fail closed: require worker-provided validation with hash binding.
// Worker sends: { workerValidated, narrativeHash, narrative, validation:{valid,errors} }
const input = $input.first().json;
if (!input.workerValidated) {
  throw new Error('Narrative not worker-validated — rejecting');
}
if (!input.narrativeHash || input.narrativeHash.length !== 64) {
  throw new Error('Missing narrativeHash from worker');
}
// The worker is authoritative for validation. n8n enforces the hash binding.
// Preserve the full envelope for downstream nodes.
if (!input.validation || !input.validation.valid) {
  return [{ json: { ...input, needsRepair: true } }];
}
return [{ json: { ...input, needsRepair: false } }];

// Same SSRF policy as primary endpoint validation.
const ALLOWED_HOSTS = new Set([
  'api.openai.com',
  'api.anthropic.com'
]);
const BLOCKED_PATTERNS = [
  /^localhost$/i, /^127\./, /^0\./, /^10\./, /^172\.1[6-9]\./, /^172\.2[0-9]\./, /^172\.3[0-1]\./, /^192\.168\./, /^169\.254\./, /^::1$/, /^fc00:/, /^fe80:/
];
const endpoint = $json._repairEndpoint || $json.modelEndpoint;
if (!endpoint || typeof endpoint !== 'string') {
  throw new Error('repairEndpoint is required');
}
let url;
try { url = new URL(endpoint); } catch (e) {
  throw new Error('repairEndpoint is not a valid URL');
}
if (url.protocol !== 'https:') throw new Error('repairEndpoint must use HTTPS');
if (!ALLOWED_HOSTS.has(url.hostname)) throw new Error('repairEndpoint host not in allowlist');
for (const pat of BLOCKED_PATTERNS) if (pat.test(url.hostname)) throw new Error('repairEndpoint blocked address');
$json._validatedRepairEndpoint = endpoint;
return [{ json: $json }];

// Final gate after primary success or repair — worker-validated response.
// Worker sends validated narrative with hash binding. n8n enforces the gate.
const result = $input.first().json;
if (!result.workerValidated) {
  throw new Error('Final validation: workerValidated missing');
}
if (!result.narrativeHash || result.narrativeHash.length !== 64) {
  throw new Error('Final validation: narrativeHash missing or invalid');
}
if (!result.validation || !result.validation.valid) {
  throw new Error('Final validation failed: ' + (result.validation?.errors || []).join('; '));
}
return [{ json: result }];
